mapper.select:

where receiver = #{receiver}

    and notify_type = #{notifyType}


    and is_read = #{readFlagQuery}


    and title like concat('%', #{title}, '%')

order by create_time desc, notify_id desc


where receiver = #{receiver} and is_read = '0'
order by create_time desc, notify_id desc
limit #{limit}

select count(*) from jc_notify_message
where receiver = #{receiver} and title = #{title}
  and create_time >= curdate() and create_time < date_add(curdate(), interval 1 day)
